#include <iostream>
#include <memory>

struct Node {
    int data{0};
    std::unique_ptr<Node> next{nullptr};
};

class SimpleStack {
private:
    std::unique_ptr<Node> top{nullptr};

public:
    bool isEmpty() const {
        return top == nullptr;
    }

    void push(int value) {
        auto newNode = std::make_unique<Node>();
        newNode->data = value;
        newNode->next = std::move(top);
        top = std::move(newNode);
    }

    void printStack() const {
        if (isEmpty()) {
            std::cout << "The stack is empty.\n";
            return;
        }
        std::cout << "The stack is:\n";
        const Node* current = top.get();
        while (current != nullptr) {
            std::cout << current->data << " --> ";
            current = current->next.get();
        }
        std::cout << "NULL\n";
    }
};

int main() {
    SimpleStack stack;
    stack.printStack();
    stack.push(3);
    stack.push(2);
    stack.push(8);
    stack.printStack();
    return 0;
}

#include <iostream>
#include <optional>
#include <utility>

class Stack {
private:
    struct Node {
        int data;
        Node* next;
        Node(int val, Node* nxt) : data(val), next(nxt) {}
    };

    Node* topPtr{nullptr};

public:
    Stack() = default;

    ~Stack() {
        while (!isEmpty()) {
            pop();
        }
    }

    Stack(const Stack&) = delete;
    Stack& operator=(const Stack&) = delete;

    bool isEmpty() const {
        return topPtr == nullptr;
    }

    void push(int value) {
        topPtr = new Node(value, topPtr);
    }

    std::optional<int> pop() {
        if (isEmpty()) {
            return std::nullopt;
        }
        Node* tempPtr = topPtr;
        int poppedValue = tempPtr->data;
        topPtr = topPtr->next;
        delete tempPtr;
        return poppedValue;
    }

    void printStack() const {
        if (isEmpty()) {
            std::cout << "The stack is empty.\n";
            return;
        }
        std::cout << "The stack is:\n";
        Node* current = topPtr;
        while (current != nullptr) {
            std::cout << current->data << " --> ";
            current = current->next;
        }
        std::cout << "NULL\n";
    }
};

int main() {
    Stack s;
    // Simulate the sequence of operations from textbook Fig. 12.9
    s.push(5);
    s.printStack();
    s.push(6);
    s.printStack();
    s.push(4);
    s.printStack();

    if (auto val = s.pop(); val.has_value()) {
        std::cout << "The popped value is " << *val << ".\n";
